gameActivityClassAdditions.insert:
/**
 * 가상 키보드가 화면 아래에서 차지하는 비율을 만분율로 돌려준다.
 * 알 수 없으면 -1.
 *
 * 픽셀이 아니라 비율로 주는 이유는 UE 가 안드로이드에서 화면 해상도를 줄여
 * 렌더링하기 때문이다. 실기기에서 1440x3120 화면이 616x1279 뷰포트로 잡혔다.
 * 픽셀을 그대로 넘기면 C++ 쪽에서 다시 실제 화면 크기를 알아내야 한다.
 */
public int AndroidThunkJava_GetImeInsetPermyriad()
{
	if (android.os.Build.VERSION.SDK_INT >= 30)
	{
		try
		{
			android.view.View DecorView = getWindow().getDecorView();
			android.view.WindowInsets Insets = DecorView.getRootWindowInsets();
			int DecorHeight = DecorView.getHeight();
			if (Insets != null && DecorHeight > 0)
			{
				int ImeBottom = Insets.getInsets(android.view.WindowInsets.Type.ime()).bottom;
				return (ImeBottom * 10000) / DecorHeight;
			}
		}
		catch (Exception e)
		{
			// 제조사 롬에 따라 던질 수 있다. 실패하면 호출부가 비율 폴백을 쓴다.
		}
	}
	return -1;
}
